// C dependencies supplied by the kernel and by the generated model are
// intentionally not reimplemented here.
// C build-time requirement: MONITOR_NAME must be supplied by the generated model.

static mut rv_this: rv_monitor = unsafe { core::mem::zeroed() };
static mut ltl_monitor_slot: i32 = RV_PER_TASK_MONITOR_INIT;

extern "C" {
    fn ltl_atoms_fetch(task: *mut task_struct, mon: *mut ltl_monitor);
    fn ltl_atoms_init(task: *mut task_struct, mon: *mut ltl_monitor, task_creation: bool);
    fn rv_get_task_monitor_slot() -> i32;
    fn rv_attach_trace_probe(name: *const core::ffi::c_char, event: *const core::ffi::c_char, handler: unsafe extern "C" fn(*mut core::ffi::c_void, *mut task_struct, u64));
    fn rv_detach_trace_probe(name: *const core::ffi::c_char, event: *const core::ffi::c_char, handler: unsafe extern "C" fn(*mut core::ffi::c_void, *mut task_struct, u64));
    fn tracepoint_synchronize_unregister();
    fn rv_put_task_monitor_slot(slot: i32);
    fn rv_react(monitor: *mut rv_monitor, fmt: *const core::ffi::c_char, ...);
    fn rv_ltl_all_atoms_known(mon: *const ltl_monitor) -> bool;
    fn ltl_start(task: *mut task_struct, mon: *mut ltl_monitor);
    fn rv_ltl_valid_state(mon: *const ltl_monitor) -> bool;
    fn ltl_possible_next_states(mon: *const ltl_monitor, state: u32, next_states: *mut core::ffi::c_ulong);
    fn ltl_atom_str(atom: i32) -> *const core::ffi::c_char;
}

unsafe fn ltl_get_monitor(task: *mut task_struct) -> *mut ltl_monitor {
    &mut (*task).rv[ltl_monitor_slot as usize].ltl_mon
}

unsafe fn ltl_task_init(task: *mut task_struct, task_creation: bool) {
    let mon = ltl_get_monitor(task);
    core::ptr::write_bytes((*mon).states.as_mut_ptr(), 0, (*mon).states.len());
    for i in 0..LTL_NUM_ATOM {
        __set_bit(i, (*mon).unknown_atoms.as_mut_ptr());
    }
    ltl_atoms_init(task, mon, task_creation);
    ltl_atoms_fetch(task, mon);
}

unsafe extern "C" fn handle_task_newtask(_data: *mut core::ffi::c_void, task: *mut task_struct, _flags: u64) {
    ltl_task_init(task, true);
}

unsafe fn ltl_monitor_init() -> i32 {
    let ret = rv_get_task_monitor_slot();
    if ret < 0 { return ret; }
    ltl_monitor_slot = ret;
    // C trace-probe registration: rv_attach_trace_probe(name, task_newtask, handle_task_newtask)
    read_lock(&tasklist_lock);
    for_each_process_thread(|_g, p| ltl_task_init(p, false));
    for_each_present_cpu(|cpu| ltl_task_init(idle_task(cpu), false));
    read_unlock(&tasklist_lock);
    0
}

unsafe fn ltl_monitor_destroy() {
    // C trace-probe deregistration: rv_detach_trace_probe(name, task_newtask, handle_task_newtask)
    tracepoint_synchronize_unregister();
    rv_put_task_monitor_slot(ltl_monitor_slot);
    ltl_monitor_slot = RV_PER_TASK_MONITOR_INIT;
}

unsafe fn ltl_illegal_state(task: *mut task_struct, _mon: *mut ltl_monitor) {
    // C generated call: CONCATENATE(trace_error_, MONITOR_NAME)(task)
    rv_react(&mut rv_this, c"rv: " /* C __stringify(MONITOR_NAME) */ .as_ptr(), (*task).comm.as_ptr());
}

unsafe fn ltl_attempt_start(task: *mut task_struct, mon: *mut ltl_monitor) {
    if rv_ltl_all_atoms_known(mon) { ltl_start(task, mon); }
}

unsafe fn ltl_atom_set(mon: *mut ltl_monitor, atom: ltl_atom, value: bool) {
    __clear_bit(atom as usize, (*mon).unknown_atoms.as_mut_ptr());
    if value { __set_bit(atom as usize, (*mon).atoms.as_mut_ptr()); }
    else { __clear_bit(atom as usize, (*mon).atoms.as_mut_ptr()); }
}

unsafe fn ltl_trace_event(task: *mut task_struct, mon: *mut ltl_monitor, next_state: *mut core::ffi::c_ulong) {
    // C DECLARE_SEQ_BUF/ snprintf/seq_buf_printf formatting is supplied by the kernel.
    // C generated call: CONCATENATE(trace_event_, MONITOR_NAME)(task, states, atoms.buffer, next)
    let _ = (task, mon, next_state);
}

unsafe fn ltl_validate(task: *mut task_struct, mon: *mut ltl_monitor) {
    let mut next_states = [0 as core::ffi::c_ulong; RV_MAX_BA_STATES as usize / (core::mem::size_of::<core::ffi::c_ulong>() * 8)];
    if !rv_ltl_valid_state(mon) { return; }
    for i in 0..RV_NUM_BA_STATES {
        if test_bit(i, (*mon).states.as_ptr()) { ltl_possible_next_states(mon, i, next_states.as_mut_ptr()); }
    }
    ltl_trace_event(task, mon, next_states.as_mut_ptr());
    core::ptr::copy_nonoverlapping(next_states.as_ptr(), (*mon).states.as_mut_ptr(), next_states.len());
    if !rv_ltl_valid_state(mon) { ltl_illegal_state(task, mon); }
}

unsafe fn ltl_atom_update(task: *mut task_struct, atom: ltl_atom, value: bool) {
    let mon = ltl_get_monitor(task);
    ltl_atom_set(mon, atom, value);
    ltl_atoms_fetch(task, mon);
    if !rv_ltl_valid_state(mon) { ltl_attempt_start(task, mon); return; }
    ltl_validate(task, mon);
}

#[allow(dead_code)]
unsafe fn ltl_atom_pulse(task: *mut task_struct, atom: ltl_atom, value: bool) {
    let mon = ltl_get_monitor(task);
    ltl_atom_update(task, atom, value);
    ltl_atom_set(mon, atom, !value);
    ltl_validate(task, mon);
}

// CONFIG_RV_MONITORS_KUNIT_TEST equivalent of RV_MON_OPS_INIT.
#[cfg(feature = "CONFIG_RV_MONITORS_KUNIT_TEST")]
const RV_MON_OPS_INIT: rv_monitor_ops = rv_monitor_ops {
    rv_this: unsafe { &raw mut rv_this },
    is_per_task: true,
    task_slot: unsafe { &raw mut ltl_monitor_slot },
};

